begin;
create extension if not exists pgtap with schema extensions;
select extensions.plan(10);
select extensions.ok(not has_function_privilege('anon','public.platform_admin_business_summary(uuid,integer)','EXECUTE'),'anonymous callers cannot read cross-merchant KPIs');
select extensions.ok(not has_function_privilege('authenticated','public.platform_admin_business_summary(uuid,integer)','EXECUTE'),'merchant JWT cannot choose an admin actor');
select extensions.ok(not has_function_privilege('authenticated','public.platform_admin_business_attention(uuid)','EXECUTE'),'attention is service authority only');
select extensions.throws_ok($$select public.platform_admin_business_summary('00000000-0000-4000-8000-000000000000',30)$$,'42501','Platform administrator access required','unknown actor denied');
select extensions.throws_ok($$select public.platform_admin_business_attention(null)$$,'42501','Platform administrator access required','null actor denied');
create temp table dashboard_actor(id uuid);
insert into dashboard_actor values(gen_random_uuid());
insert into auth.users(id,email,aud,role) select id,'dashboard-'||id||'@example.com','authenticated','authenticated' from dashboard_actor;
insert into public.platform_admins(user_id,role) select id,'support' from dashboard_actor;
select extensions.lives_ok(format('select public.platform_admin_business_summary(%L,30)',id),'Support may read business summary') from dashboard_actor;
select extensions.throws_ok(format('select public.platform_admin_business_summary(%L,31)',id),'22023','Business period must be 7, 30 or 90 days','invalid period rejected') from dashboard_actor;
select extensions.is((public.platform_admin_business_summary(id,30)->>'generatedAt')::timestamptz-(public.platform_admin_business_summary(id,30)->>'startAt')::timestamptz,interval '30 days','current period has explicit boundaries') from dashboard_actor;
select extensions.is((public.platform_admin_business_summary(id,30)->>'startAt')::timestamptz-(public.platform_admin_business_summary(id,30)->>'previousStartAt')::timestamptz,interval '30 days','prior period has equal duration') from dashboard_actor;
select extensions.ok(jsonb_array_length(public.platform_admin_business_attention(id)->'items')<=20,'attention response is bounded') from dashboard_actor;
select * from extensions.finish();
rollback;
